mod tests {
    use std::collections::HashSet;

    use super::*;

    #[test]
    fn bootstrap_catalog_lengths_and_resource_ids_are_stable() {
        let catalogs: &[(&[&str], usize)] = &[
            (VANILLA_TRIM_MATERIAL_KEYS, 11),
            (VANILLA_TRIM_PATTERN_KEYS, 18),
            (VANILLA_JUKEBOX_SONG_KEYS, 21),
            (VANILLA_POTION_KEYS, 46),
            (VANILLA_VILLAGER_TYPE_KEYS, 7),
            (VANILLA_WOLF_SOUND_VARIANT_KEYS, 7),
            (VANILLA_WOLF_VARIANT_KEYS, 9),
            (VANILLA_INSTRUMENT_KEYS, 8),
        ];
        for (entries, expected_len) in catalogs {
            assert_eq!(entries.len(), *expected_len);
            let resources: HashSet<_> = entries.iter().copied().collect();
            assert_eq!(resources.len(), entries.len());
            assert!(entries.iter().all(|entry| entry.starts_with("minecraft:")));
        }
        assert_eq!(VANILLA_BANNER_PATTERNS.len(), 43);
        assert_eq!(VANILLA_PAINTING_VARIANTS.len(), 51);
        assert_eq!(VANILLA_ENCHANTMENTS.len(), 43);
        let banner_resources: HashSet<_> = VANILLA_BANNER_PATTERNS
            .iter()
            .map(|entry| entry.resource_id)
            .collect();
        assert_eq!(banner_resources.len(), VANILLA_BANNER_PATTERNS.len());
        let painting_resources: HashSet<_> = VANILLA_PAINTING_VARIANTS
            .iter()
            .map(|entry| entry.key)
            .collect();
        assert_eq!(painting_resources.len(), VANILLA_PAINTING_VARIANTS.len());
        let enchantment_resources: HashSet<_> = VANILLA_ENCHANTMENTS
            .iter()
            .map(|entry| entry.resource_id)
            .collect();
        assert_eq!(enchantment_resources.len(), VANILLA_ENCHANTMENTS.len());
    }

    #[test]
    fn bootstrap_catalog_preserves_vanilla_registration_order() {
        assert_eq!(
            VANILLA_TRIM_MATERIAL_KEYS.first(),
            Some(&"minecraft:quartz")
        );
        assert_eq!(VANILLA_TRIM_PATTERN_KEYS.last(), Some(&"minecraft:bolt"));
        assert_eq!(
            VANILLA_JUKEBOX_SONG_KEYS.last(),
            Some(&"minecraft:lava_chicken")
        );
        assert_eq!(VANILLA_POTION_KEYS.get(3), Some(&"minecraft:awkward"));
        assert_eq!(VANILLA_VILLAGER_TYPE_KEYS.last(), Some(&"minecraft:taiga"));
        assert_eq!(
            VANILLA_WOLF_SOUND_VARIANT_KEYS.get(1),
            Some(&"minecraft:puglin")
        );
        assert_eq!(VANILLA_WOLF_VARIANT_KEYS.last(), Some(&"minecraft:striped"));
        assert_eq!(
            VANILLA_INSTRUMENT_KEYS.last(),
            Some(&"minecraft:dream_goat_horn")
        );
        assert_eq!(
            VANILLA_BANNER_PATTERNS.get(31).unwrap().resource_id,
            "minecraft:gradient"
        );
        assert_eq!(
            VANILLA_BANNER_PATTERNS.get(34).unwrap().resource_id,
            "minecraft:curly_border"
        );
        assert!(!VANILLA_PAINTING_VARIANTS.get(19).unwrap().has_author);
        assert_eq!(
            (
                VANILLA_PAINTING_VARIANTS.get(50).unwrap().width,
                VANILLA_PAINTING_VARIANTS.get(50).unwrap().height
            ),
            (3, 3)
        );
        assert_eq!(
            VANILLA_ENCHANTMENTS.get(13).unwrap().resource_id,
            "minecraft:sharpness"
        );
        assert_eq!(VANILLA_ENCHANTMENTS.get(13).unwrap().max_level, 5);
    }
}
